package org.apache.commons.lang;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.apache.commons.lang.exception.NestableRuntimeException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class StringEscapeUtils_escapeHtml_TriageGen0Test {

    @Test(expected = IllegalArgumentException.class)
    public void testEscapeHtml_WriterIsNull() throws IOException {
        StringEscapeUtils.escapeHtml(null, "test");
    }

    @Test
    public void testEscapeHtml_StringIsNull() throws IOException {
        StringWriter writer = new StringWriter();
        StringEscapeUtils.escapeHtml(writer, null);
        assertEquals("", writer.toString());
    }

    @Test
    public void testEscapeHtml_NormalString() throws IOException {
        StringWriter writer = new StringWriter();
        StringEscapeUtils.escapeHtml(writer, "Hello World");
        assertEquals("Hello World", writer.toString());
    }

    @Test
    public void testEscapeHtml_HtmlSpecialCharacters() throws IOException {
        StringWriter writer = new StringWriter();
        StringEscapeUtils.escapeHtml(writer, "<>&\"'");
        // Based on HTML40 escaping standards used by Commons Lang
        // < -> &lt;
        // > -> &gt;
        // & -> &amp;
        // " -> &quot;
        // ' -> &#39; (or &apos; depending on specific Entities implementation, 
        // but HTML40 usually maps to &lt; &gt; &amp; &quot; &#39;)
        String result = writer.toString();
        assertEquals("&lt;&gt;&amp;&quot;&#39;", result);
    }

    @Test
    public void testEscapeHtml_EmptyString() throws IOException {
        StringWriter writer = new StringWriter();
        StringEscapeUtils.escapeHtml(writer, "");
        assertEquals("", writer.toString());
    }

    @Test
    public void testEscapeHtml_WriterThrowsIOException() throws IOException {
        Writer throwingWriter = new Writer() {
            @Override
            public void write(char[] cbuf, int off, int len) throws IOException {
                throw new IOException("Simulated IO Error");
            }

            @Override
            public void flush() throws IOException {}

            @Override
            public void close() throws IOException {}
        };

        try {
            StringEscapeUtils.escapeHtml(throwingWriter, "test");
            org.junit.Assert.fail("Expected IOException to be thrown");
        } catch (IOException e) {
            assertEquals("Simulated IO Error", e.getMessage());
        }
    }
}
